properties.query:
let windowSize = 2h;

// S34: Recon/Credential Probe
let S34 =
    UAVOpAudit_CL
    | where TimeGenerated > ago(windowSize)
    | where EventType == 'login_failure'
    | extend Stage = 'S34', Operator = tostring(Operator)
    | where isnotempty(Operator)
    | project TimeGenerated, Stage, Operator;

// S95: Exfil Staging
let S95 =
    UAVExfilFlow_CL
    | where TimeGenerated > ago(windowSize)
    | where DataClass == 'staged_bulk'
    | extend Stage = 'S95', Operator = tostring(Operator)
    | where isnotempty(Operator)
    | project TimeGenerated, Stage, Operator;

// S93: Bulk SAR/Imagery Exfil
let S93 =
    UAVExfilFlow_CL
    | where TimeGenerated > ago(windowSize)
    | where DataClass in ('sar_bulk','imagery_bulk')
    | extend Stage = 'S93', Operator = tostring(Operator)
    | where isnotempty(Operator)
    | project TimeGenerated, Stage, Operator;

union S34, S95, S93
| summarize StagesSeen = make_set(Stage), StageCount = dcount(Stage), FirstSeen = min(TimeGenerated), LastSeen = max(TimeGenerated) by Operator
| where StageCount >= 2
| extend CampaignType = "C12_자격증명_스테이징_대량유출"
| extend StepSummary = strcat("Stages=", tostring(StagesSeen), " | First=", tostring(FirstSeen), " | Last=", tostring(LastSeen))
| extend Severity = "High"
| project FirstSeen, LastSeen, Operator, StagesSeen, StageCount, CampaignType, StepSummary, Severity
